using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define tools the agent can use
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
            // Simulated web search results
            return $"""
                Search results for "{query}":
                1. "{query}" - Wikipedia overview covering key concepts and history.
                2. Recent advances in {query} - Nature article (2025) discussing latest developments.
                3. A beginner's guide to {query} - TechReview, practical applications explained.
                """;
        },
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),
    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [NoteTaker] Saved note: \"{title}\"");
            return $"Note saved: \"{title}\"";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),
    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all saved research notes."),
};

// Configure the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Using the web_search tool to find information (make multiple searches to cover different aspects).
        2. Using the take_note tool to record key findings as you go.
        3. After gathering enough information, use get_notes to review your notes.
        4. Finally, provide a comprehensive summary of your research findings.

        Be thorough but concise. Search for multiple aspects of the topic.
        """,
    Tools = tools,
};

// Run the agent
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"\n## {note.Title}");
    Console.WriteLine(note.Content);
}

Console.WriteLine("\nResearch complete.");

