var noteService = host.Services.GetRequiredService<NoteService>();

// Define tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
            return $"""
                Search results for "{query}":
                1. "{query}" - Wikipedia overview covering key concepts and history.
                2. Recent advances in {query} - Nature article (2025) discussing latest developments.
                3. A beginner's guide to {query} - TechReview, practical applications explained.
                """;
        },
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),
    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [NoteTaker] Saved note: \"{title}\"");
            return $"Note saved: \"{title}\"";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),
    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all saved research notes."),
};

// Configure the agent with tools and instructions
var instructions = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Using the web_search tool to find information (make multiple searches to cover different aspects).
    2. Using the take_note tool to record key findings as you go.
    3. After gathering enough information, use get_notes to review your notes.
    4. Finally, provide a comprehensive summary of your research findings.

    Be thorough but concise. Search for multiple aspects of the topic.
    """;

